    "sk-sk": "sk",
    "hu-hu": "hu",
    "ro-ro": "ro",
    "nl-nl": "nl",
    "nl-be": "nl",
    "sv-se": "sv",
    "da-dk": "da",
    "fi-fi": "fi",
    "no": "nb",
    "nb-no": "nb",
