    languages: SUPPORTED_LANGUAGES,
    normalizeLanguage,
    detectLanguage,
    resolveLanguage,
    setLanguage,
    translate,
    translatePage,
    get locale() { return activeLocale; },
    get requestedLanguage() { return requestedLanguage; }
